const suppliers = [
  { name: 'Northwind', tag: 'supplier/northwind', email: 'billing@northwind.com' },
  { name: 'Contoso', tag: 'supplier/contoso', email: 'ap@contoso.com' },
  { name: 'Globex', tag: 'supplier/globex', email: 'finance@globex.example' }
];

const queryParts = suppliers.map((supplier) => {
  const filters = [`label:${supplier.tag}`, `from:${supplier.email}`];
  return `(${filters.join(' OR ')})`;
});

const gmailQuery = `${queryParts.join(' OR ')} has:attachment filename:pdf`;

return [
  {
    json: {
      suppliers,
      gmailQuery,
      runId: $execution.id
    }
  }
];

const flattened = [];
for (const item of items) {
  const binaryKeys = Object.keys(item.binary || {});
  if (!binaryKeys.length) {
    continue;
  }

  for (const key of binaryKeys) {
    const attachment = item.binary[key];
    if (!attachment || attachment.fileExtension?.toLowerCase() !== 'pdf') {
      continue;
    }

    flattened.push({
      json: {
        supplierHint: item.json.from?.value?.[0]?.address || null,
        gmailAccount: item.json.gmailAccount || null,
        messageId: item.json.id,
        threadId: item.json.threadId,
        subject: item.json.subject,
        historyId: item.json.historyId,
        runId: item.json.runId || null
      },
      binary: {
        data: attachment
      }
    });
  }
}
return flattened;

const projectId = $env.FIREBASE_PROJECT_ID || 'your-project-id';
const collectionPath = `projects/${projectId}/databases/(default)/documents/invoiceHistory`;

function toFirestoreValue(value) {
  if (value === null || value === undefined) {
    return { nullValue: null };
  }
  if (typeof value === 'number') {
    return { doubleValue: value };
  }
  if (typeof value === 'boolean') {
    return { booleanValue: value };
  }
  if (typeof value === 'string') {
    return { stringValue: value };
  }
  if (Array.isArray(value)) {
    return { arrayValue: { values: value.map((entry) => toFirestoreValue(entry)) } };
  }
  if (typeof value === 'object') {
    return { mapValue: { fields: Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, toFirestoreValue(entry)])) } };
  }
  return { stringValue: String(value) };
}

return items.map(item => {
  const source = item.json || {};
  const rawOutput = source.output ?? source.aiExtraction ?? null;
  let parsedOutput = {};
  if (typeof rawOutput === 'string') {
    try {
      parsedOutput = JSON.parse(rawOutput);
    } catch (error) {
      parsedOutput = { notes: `Unable to parse AI output: ${error.message}` };
    }
  } else if (rawOutput && typeof rawOutput === 'object') {
    parsedOutput = rawOutput;
  }
  const messageId = source.message_id || source.messageId || 'unknown-message';
  const firestoreEndpoint = `https://firestore.googleapis.com/v1/${collectionPath}?documentId=${encodeURIComponent(messageId)}`;
  const aiFields = {};
  if (parsedOutput && typeof parsedOutput === 'object') {
    for (const [key, value] of Object.entries(parsedOutput)) {
      if (['firestoreEndpoint','payload','pdfBase64','output'].includes(key)) {
        continue;
      }
      aiFields[key] = toFirestoreValue(value);
    }
  }
  return {
    json: {
      firestoreEndpoint,
      payload: {
        fields: {
          messageId: { stringValue: messageId },
          gmailAccount: { stringValue: source.gmail_account || source.gmailAccount || '' },
          supplierHint: { stringValue: source.supplier_hint || source.supplierHint || '' },
          subject: { stringValue: source.subject || '' },
          runId: { stringValue: source.run_id || source.runId || '' },
          processedAt: { timestampValue: new Date().toISOString() },
          aiExtraction: { mapValue: { fields: aiFields } }
        }
      }
    }
  };
});

